#pragma once

#include <cstddef>
#include <cstdint>
#include <string_view>

namespace pef::build {

/// Product identity. The build number is 4.2.0.1 even though the changelog tops out at
/// 2.1, because in this product category seniority is earned fast and version numbers
/// are earned faster. The authoritative machine-readable version lives in the
/// SKSEPluginInfo declaration generated by CMake; this constant is its shadow for
/// reports and logs, and the two cannot drift because neither is hand-written twice.
inline constexpr std::string_view version{"4.2.0.1"};

/// The "b" in 4.2.0.1b. It stands for "beta", "build", and "believed", in that order.
inline constexpr std::string_view channel{"b"};

inline constexpr std::string_view name{"Placebo Engine Framework"};
inline constexpr std::string_view short_name{"PEF"};
inline constexpr std::string_view author{"PEF Consortium"};

inline constexpr std::string_view tagline{
    "The first fully instrumented Skyrim engine mod that provably does nothing."};

/// The number of engine call sites PEF hooks. This is a marketing constant with the full
/// protection of engineering discipline: it lives in code, the installer treats it as a
/// hard budget, and it must never change, because the README has already quoted it.
inline constexpr std::size_t hook_budget{47};

/// The audit period asserted by the product specification, in milliseconds. Unlike the
/// performance settings, this one is load-bearing: the instrumentation is the product.
inline constexpr std::uint32_t audit_interval_ms{250};

/// Trampoline capacity, in bytes. Each five-byte call-site witness consumes roughly
/// sixteen bytes of trampoline; 47 hooks want under a kilobyte, and the rest is the
/// safety margin that lets the budget be a marketing constant without consequence.
inline constexpr std::size_t trampoline_bytes{8192};

} // namespace pef::build
